{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this packing plan — are we minimizing the number of containers used, maximizing the total weight (or value) of goods shipped, or something else?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options for one decision."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Do all available goods have to be shipped in this plan, or is it acceptable to leave some units of any type unshipped (i.e., the per-type totals are upper bounds, not exact requirements)?"
  ],
  "rationale": "The response asks a single clarification question regarding whether shipment quantities are exact requirements or upper bounds."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are the goods units indivisible (each type's units must be whole integers in each container), or can they be treated as continuous amounts?"
  ],
  "rationale": "The response asks a single clarification question regarding the granularity of the units (integer vs. continuous), which constitutes one independent decision point."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there a fixed, known number of containers available to choose from (i.e., a maximum number of containers we can use), or is the number of containers unbounded and we simply decide how many to use?"
  ],
  "rationale": "The response asks a single clarification question regarding the constraint on the number of containers, presenting a binary choice (fixed vs. unbounded) that constitutes one independent query."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Since the number of containers is unbounded, do we need to cap it at some maximum (for example, the largest number that could possibly be needed given the available goods), or is it fine to let the model decide the count freely?"
  ],
  "rationale": "The response asks a single clarification question regarding whether to impose a cap on the number of containers or allow the model to decide freely."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there any requirement that every container must contain at least one unit of each of the five types A, B, C, D, and E, or is it acceptable for a container to contain zero units of some types (as long as the stated rules — minimum weight, minimum D, and the A-implies-C rule — are satisfied)?"
  ],
  "rationale": "The response asks a single clarification question regarding whether containers must include all five types or if zero units of some types are permitted."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there any requirement that the total weight of each container must be exactly 60 tons, or is it fine for a container to be loaded anywhere between 18 and 60 tons (inclusive)?"
  ],
  "rationale": "The response asks for a single policy choice regarding container weight constraints (exact 60 tons vs. range 18-60 tons), which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there any requirement that the total number of units of each type shipped must be a specific target, or is it purely an upper bound (i.e., we can ship any amount up to the available quantity of each type)?"
  ],
  "rationale": "The response asks a single clarification question regarding whether shipment quantities are fixed targets or upper bounds."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there any requirement that the total weight of goods shipped must be at least some minimum amount, or is it acceptable to ship any amount (including zero) as long as the per-container rules are satisfied?"
  ],
  "rationale": "The response asks a single clarification question regarding the minimum total weight requirement, presenting a binary choice (minimum exists vs. no minimum) which constitutes one independent query."
}

{
  "action": "question",
